// V4-04 KPB2 reader against packs produced by tools/story_pack.py
// (tests/fixtures/kpb2, regenerated by tests/test_v4_kpb2.py).
// Usage: test_content_pack_reader <dir with golden_book.kpb, golden_kpb1.kpb>
#include "kid_app/content_pack_reader.h"
#include "kid_app/memory_store.h"
#include "kid_app/scene_model.h"
#include "kid_app/story_pack_file_port.h"
#include "kid_app/story_pack_reader.h"

#include <algorithm>
#include <cassert>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <functional>
#include <iostream>
#include <iterator>
#include <string>
#include <vector>

using namespace kid_app;

namespace {

class MemoryFile final : public StoryPackFile {
public:
    explicit MemoryFile(std::vector<uint8_t> b) : bytes(std::move(b)) {}
    uint64_t Size() const override { return bytes.size(); }
    bool ReadAt(uint32_t pos, void* dst, size_t size) override {
        if (!dst || fail_read || uint64_t(pos) + size > bytes.size()) return false;
        std::copy_n(bytes.data() + pos, size, static_cast<uint8_t*>(dst));
        return true;
    }
    std::vector<uint8_t> bytes;
    bool fail_read = false;
};

uint32_t Crc(const uint8_t* d, size_t n) {
    uint32_t c = 0xFFFFFFFFu;
    for (size_t i = 0; i < n; ++i) {
        c ^= d[i];
        for (int k = 0; k < 8; ++k) c = (c >> 1) ^ ((c & 1u) ? 0xEDB88320u : 0u);
    }
    return ~c;
}
uint32_t Get32(const std::vector<uint8_t>& b, size_t at) {
    return uint32_t(b[at]) | (uint32_t(b[at + 1]) << 8) |
           (uint32_t(b[at + 2]) << 16) | (uint32_t(b[at + 3]) << 24);
}
void Put16(std::vector<uint8_t>& b, size_t at, uint16_t v) {
    b[at] = static_cast<uint8_t>(v);
    b[at + 1] = static_cast<uint8_t>(v >> 8);
}
void Put32(std::vector<uint8_t>& b, size_t at, uint32_t v) {
    for (int i = 0; i < 4; ++i) b[at + i] = static_cast<uint8_t>(v >> (8 * i));
}
// Re-seal tables + header so a mutation reaches the semantic checks.
void Reseal(std::vector<uint8_t>& b) {
    const uint32_t data = Get32(b, 40);
    Put32(b, 60, Crc(b.data() + 96, data - 96));
    Put32(b, 92, Crc(b.data(), 92));
}
std::vector<uint8_t> Load(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    assert(in);
    return {std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>()};
}
bool Opens(std::vector<uint8_t> bytes) {
    MemoryFile file(std::move(bytes));
    ContentPackReader reader;
    const bool ok = reader.Open(file);
    assert(ok == reader.Ready());
    return ok;
}

constexpr size_t kQuestionAt = 96 + 2 * 96;  // golden: 2 page records
constexpr char kNotChild[] = "（测试样例，非儿童内容）";

void TestKpb2(const std::string& dir) {
    StoryPackFilePort port;
    assert(port.OpenBook(dir.c_str(), "golden_book"));
    ContentPackReader r;
    assert(r.Open(port));
    assert(r.Format() == PackFormat::Kpb2 && r.Type() == PackType::Book);
    assert(r.ContentId() == 101 && r.Revision() == 1);
    assert(r.PageCount() == 2 && r.QuestionCount() == 2);
    char text[1281]{};
    assert(r.ReadTitle(text, sizeof(text)));
    assert(std::string(text) == std::string("灰度样例书") + kNotChild);
    assert(!r.ReadTitle(text, 8));

    ContentPage p1{}, p2{};
    assert(r.Page(1, &p1) && r.Page(2, &p2) && !r.Page(0, &p1) && !r.Page(3, &p1));
    assert(p1.has_grey && p1.question_count == 2 && p1.question_first == 0);
    assert(p1.mono.bytes == ContentPackReader::kMonoBytes);
    assert(p1.grey.bytes == ContentPackReader::kGreyBytes);
    assert(p1.pcm.bytes == 4800 && p1.sample_rate == 24000 && p1.channels == 1);
    assert(!p2.has_grey && p2.question_count == 0 && p2.question_first == 2);
    assert(p2.grey.offset == 0 && p2.grey.bytes == 0);

    // Grey: four bands, 0 black .. 3 white, 4 px per byte MSB first.
    std::vector<uint8_t> grey(ContentPackReader::kGreyBytes, 0xAA);
    assert(!r.ReadGrey(1, grey.data(), grey.size() - 1));
    assert(r.ReadGrey(1, grey.data(), grey.size()));
    assert(grey[0] == 0x00 && grey[50] == 0x55 && grey[100] == 0xAA &&
           grey[199] == 0xFF && grey[479 * 200 + 50] == 0x55);
    assert(!r.ReadGrey(2, grey.data(), grey.size()));
    std::vector<uint8_t> row(200);
    assert(r.ReadGreyRows(1, 479, 1, row.data(), row.size()));
    assert(std::equal(row.begin(), row.end(), grey.begin() + 479 * 200));
    assert(!r.ReadGreyRows(1, 479, 2, row.data(), 400));
    assert(!r.ReadGreyRows(1, 0, 2, row.data(), row.size()));
    assert(!r.ReadGreyRows(1, 0, 0, row.data(), row.size()));

    std::vector<uint8_t> hi(100), lo(100);
    assert(SplitGreyPlanes(grey.data(), 200, hi.data(), lo.data()));
    assert(hi[0] == 0x00 && lo[0] == 0x00);    // level 0
    assert(hi[25] == 0x00 && lo[25] == 0xFF);  // level 1
    assert(hi[50] == 0xFF && lo[50] == 0x00);  // level 2
    assert(hi[75] == 0xFF && lo[75] == 0xFF);  // level 3
    assert(!SplitGreyPlanes(grey.data(), 3, hi.data(), lo.data()));

    // 1-bit fallback through the board's StoryPackReader view.
    StoryPackReader story;
    assert(story.Open(port) && story.PageCount() == 2);
    assert(story.Content().Format() == PackFormat::Kpb2);
    MonoFrame frame;
    assert(story.ReadFrame(1, frame));
    assert(frame.IsBlack(0, 0) && !frame.IsBlack(200, 0) && frame.IsBlack(201, 0));
    assert(frame.IsBlack(200, 1) && !frame.IsBlack(400, 0) && frame.IsBlack(401, 1));
    assert(!frame.IsBlack(799, 479));
    assert(story.ReadFrame(2, frame));
    assert(frame.IsBlack(0, 0) && !frame.IsBlack(1, 0) && frame.IsBlack(400, 150));
    StoryPageInfo info{};
    assert(story.Page(1, &info) && info.image_bytes == StoryPackReader::kImageBytes);
    assert(info.image_offset == p1.mono.offset && info.pcm_bytes == 4800);
    std::vector<uint8_t> pcm(4800);
    assert(story.ReadPcm(1, 0, pcm.data(), pcm.size()));
    assert(!story.ReadPcm(1, 1, pcm.data(), 2));
    assert(story.ReadText(2, text, sizeof(text)));
    assert(std::string(text) == std::string("黑色方块。") + kNotChild);

    // Questions.
    ContentQuestion like{}, quiz{}, none{};
    assert(r.Question(1, 0, &like) && r.Question(1, 1, &quiz));
    assert(!r.Question(1, 2, &none) && !r.Question(2, 0, &none));
    assert(like.page == 1 && like.index == 0 && like.option_count == 3);
    assert(like.correct == 0 && !like.allow_voice && like.like_slot == 1);
    assert(like.options[0].id == 3 && like.options[0].counts_as_like);
    assert(like.options[1].id == 4 && like.options[1].counts_as_like);
    assert(like.options[2].id == 0xFF03 && !like.options[2].counts_as_like);
    assert(like.options[2].box.x == 576 && like.options[2].box.y == 336 &&
           like.options[2].box.w == 48 && like.options[2].box.h == 48);
    const PageRect hit = HighlightRect(like.options[0]);
    assert(hit.x == 88 && hit.y == 312 && hit.w == 80 && hit.h == 80);
    assert(!like.IsCorrect(0) && !like.IsCorrect(2));
    assert(quiz.correct == 1 && quiz.allow_voice && quiz.like_slot == 0);
    assert(quiz.options[0].id == 0xFF01 && quiz.options[1].id == 0xFF02);
    assert(quiz.IsCorrect(0) && !quiz.IsCorrect(1) && !quiz.IsCorrect(2));

    assert(r.ReadPromptText(like, text, sizeof(text)));
    assert(std::string(text) == "你最喜欢哪个小动物？");
    assert(r.ReadOptionLabel(like, 0, text, sizeof(text)));
    assert(std::string(text) == "小兔子");
    assert(r.ReadOptionLabel(quiz, 1, text, sizeof(text)));
    assert(std::string(text) == "方形");
    assert(!r.ReadOptionLabel(quiz, 2, text, sizeof(text)));
    assert(r.ReadPromptPcm(like, 0, pcm.data(), 2400));
    assert(!r.ReadPromptPcm(like, 0, pcm.data(), 2402));
    assert(!r.ReadPromptPcm(like, 1, pcm.data(), 2));
    assert(r.ReadOptionPcm(like, 2, 0, pcm.data(), 960));
    assert(!r.ReadOptionPcm(like, 2, 0, pcm.data(), 962));
    assert(!r.ReadOptionPcm(quiz, 2, 0, pcm.data(), 2));

    std::vector<uint8_t> icon(512);
    assert(!r.ReadOptionIcon(like, 0, icon.data(), 511));
    assert(r.ReadOptionIcon(like, 0, icon.data(), icon.size()));
    assert(icon[0] == 0x00);  // 4 px black border
    MonoFrame canvas;
    assert(r.BlitOptionIcon(like, 0, canvas));
    assert(canvas.IsBlack(96, 320) && canvas.IsBlack(159, 383));
    assert(!canvas.IsBlack(106, 330));  // interior white
    assert(!canvas.IsBlack(95, 320) && !canvas.IsBlack(160, 320));
    assert(!r.BlitOptionIcon(like, 3, canvas));

    // ADR-012: only a dial pick of a like option becomes a memory event.
    MemoryEvent e{};
    assert(ChoiceMemoryEvent(like, 0, 77, 9, &e));
    assert(e.kind == MemoryEventKind::PreferenceChosen &&
           e.source == MemorySource::DialChoice && e.id == 77 && e.day == 9 &&
           e.slot == 1 && e.option == 3);
    MemoryStore memory;
    assert(memory.Apply(e) == MemoryResult::Applied);
    uint16_t chosen = 0;
    assert(memory.FindPreference(1, &chosen) && chosen == 3);
    assert(!ChoiceMemoryEvent(like, 2, 78, 9, &e));  // "都喜欢" is not a like
    assert(!ChoiceMemoryEvent(quiz, 0, 79, 9, &e));  // quiz never writes memory
    assert(!ChoiceMemoryEvent(like, 0, 0, 9, &e));
    assert(!ChoiceMemoryEvent(like, 3, 80, 9, &e));
    assert(BookFinishedMemoryEvent(r, 81, 9, &e));
    assert(e.kind == MemoryEventKind::BookFinished &&
           e.source == MemorySource::Device && e.option == 101);
    assert(memory.Apply(e) == MemoryResult::Applied);

    port.Close();
    assert(!r.ReadMono(1, grey.data(), grey.size()));
}

void TestKpb1(const std::string& dir) {
    StoryPackFilePort port;
    assert(port.OpenBook(dir.c_str(), "golden_kpb1"));
    ContentPackReader r;
    assert(r.Open(port));
    assert(r.Format() == PackFormat::Kpb1 && r.ContentId() == 0 && r.Revision() == 0);
    assert(r.PageCount() == 1 && r.QuestionCount() == 0);
    char text[64]{};
    assert(!r.ReadTitle(text, sizeof(text)));
    std::vector<uint8_t> grey(ContentPackReader::kGreyBytes);
    assert(!r.ReadGrey(1, grey.data(), grey.size()));
    ContentQuestion q{};
    assert(!r.Question(1, 0, &q));
    MemoryEvent e{};
    assert(!BookFinishedMemoryEvent(r, 1, 0, &e));
    StoryPackReader story;
    assert(story.Open(port));
    MonoFrame frame;
    assert(story.ReadFrame(1, frame) && frame.IsBlack(0, 0) && !frame.IsBlack(1, 0));
    StoryPageInfo info{};
    assert(story.Page(1, &info) && info.pcm_bytes == 4800 && info.sample_rate == 24000);
}

void TestCorruption(const std::string& dir) {
    const std::vector<uint8_t> good = Load(dir + "/golden_book.kpb");
    assert(Opens(good));
    MemoryFile file(good);
    ContentPackReader r;
    assert(r.Open(file));
    ContentPage p1{};
    ContentQuestion like{};
    assert(r.Page(1, &p1) && r.Question(1, 0, &like));
    const ContentSegment label = like.options[0].label;  // "小兔子": 9 B + pad
    assert(label.bytes % 4 != 0);

    const std::vector<std::pair<const char*, std::function<void(std::vector<uint8_t>&)>>>
        bad = {
            {"truncated", [](std::vector<uint8_t>& b) { b.pop_back(); }},
            {"trailing", [](std::vector<uint8_t>& b) { b.insert(b.end(), 4, 0); }},
            {"header crc", [](std::vector<uint8_t>& b) { b[92] ^= 1; }},
            {"table crc", [](std::vector<uint8_t>& b) { b[96] ^= 1; }},
            {"grey crc", [&](std::vector<uint8_t>& b) { b[p1.grey.offset + 10] ^= 1; }},
            {"padding", [&](std::vector<uint8_t>& b) { b[label.offset + label.bytes] = 1; }},
            {"sound pack type", [](std::vector<uint8_t>& b) { Put16(b, 8, 2); Reseal(b); }},
            {"version", [](std::vector<uint8_t>& b) { Put16(b, 4, 3); Reseal(b); }},
            {"content id 0", [](std::vector<uint8_t>& b) { Put16(b, 16, 0); Reseal(b); }},
            {"page flags", [](std::vector<uint8_t>& b) { Put16(b, 96 + 2, 3); Reseal(b); }},
            {"3 questions", [](std::vector<uint8_t>& b) { Put16(b, 96 + 6, 3); Reseal(b); }},
            {"quiz like", [](std::vector<uint8_t>& b) {
                 b[kQuestionAt + 192 + 32 + 2] = 1; Reseal(b); }},
            {"like answer", [](std::vector<uint8_t>& b) { b[kQuestionAt + 4] = 1; Reseal(b); }},
            {"no like option", [](std::vector<uint8_t>& b) {
                 b[kQuestionAt + 32 + 2] = 0; b[kQuestionAt + 32 + 48 + 2] = 0; Reseal(b); }},
            {"overlap", [](std::vector<uint8_t>& b) {
                 Put16(b, kQuestionAt + 32 + 48 + 4, 112); Reseal(b); }},
            {"unaligned x", [](std::vector<uint8_t>& b) {
                 Put16(b, kQuestionAt + 32 + 4, 100); Reseal(b); }},
            {"off page", [](std::vector<uint8_t>& b) {
                 Put16(b, kQuestionAt + 32 + 6, 420); Reseal(b); }},
            {"icon size", [](std::vector<uint8_t>& b) {
                 Put16(b, kQuestionAt + 32 + 8, 72); Reseal(b); }},
            {"question page", [](std::vector<uint8_t>& b) {
                 Put16(b, kQuestionAt, 2); Reseal(b); }},
            {"unused option", [](std::vector<uint8_t>& b) {
                 b[kQuestionAt + 192 + 32 + 2 * 48] = 1; Reseal(b); }},
        };
    for (const auto& c : bad) {
        std::vector<uint8_t> b = good;
        c.second(b);
        if (Opens(b)) {
            std::cerr << "accepted corrupt package: " << c.first << "\n";
            assert(false);
        }
    }
    MemoryFile unreadable(good);
    unreadable.fail_read = true;
    assert(!r.Open(unreadable) && !r.Ready());
    std::vector<uint8_t> junk(good.begin(), good.begin() + 200);
    junk[3] = '3';
    assert(!Opens(junk));
}

}  // namespace

int main(int argc, char** argv) {
    assert(argc == 2);
    const std::string dir = argv[1];
    TestKpb2(dir);
    TestKpb1(dir);
    TestCorruption(dir);
    std::cout << "PASS: KPB2 grey/mono pages, questions, memory mapping, KPB1 "
                 "compatibility and strict rejection\n";
    return 0;
}
